# Helper: extract metrics from an experiment
def extract_metrics(eid, edata):
    """Extract key metrics from experiment data"""
    result = edata.get('result', {}) or {}
    conclusion = edata.get('conclusion', '') or ''
    spec = edata.get('spec', {}) or {}
    status = edata.get('status', 'N/A')

    # Metrics might be in various places
    metrics = result.get('metrics', {}) or {}

    info = {
        'exp_id': eid,
        'status': status,
        'conclusion': conclusion[:300] if conclusion else '',
    }

    # Try to find PR, ISR, H7, H1, N-H in metrics or result
    for key in ['prove_rate', 'PR', 'pr', 'proved_rate']:
        if key in metrics:
            info['PR'] = metrics[key]
        if key in result:
            info['PR'] = result[key]

    for key in ['isr_star', 'ISR*', 'isr', 'ISR', 'proved_only_isr', 'isr_proved_only']:
        if key in metrics:
            info['ISR*'] = metrics[key]
        if key in result:
            info['ISR*'] = result[key]

    for key in ['H7', 'h7', 'H7%', 'h7_pct', 'hacking_7']:
        if key in metrics:
            info['H7%'] = metrics[key]
        if key in result:
            info['H7%'] = result[key]

    for key in ['H1', 'h1', 'H1%', 'h1_pct', 'hacking_1']:
        if key in metrics:
            info['H1%'] = metrics[key]
        if key in result:
            info['H1%'] = result[key]

    for key in ['NH', 'nh', 'N-H%', 'nh_pct', 'non_hacking', 'N-H']:
        if key in metrics:
            info['N-H%'] = metrics[key]
        if key in result:
            info['N-H%'] = result[key]

    # Also dump all result keys for debugging
    info['result_keys'] = list(result.keys()) if isinstance(result, dict) else str(type(result))
    info['metrics_keys'] = list(metrics.keys()) if isinstance(metrics, dict) else str(type(metrics))

    return info

# Let's first look at one experiment in detail to understand the structure
sample_ids = ['exp1-random-b03-s43-r4', 'exp1-isr-b03-s43-r3', 'plan009-sft-baseline-s42-r4']
